package br.com.inframonitor.usuario.bootstrap;
import br.com.inframonitor.usuario.entity.*; import br.com.inframonitor.usuario.repository.UsuarioRepository; import org.springframework.boot.ApplicationRunner; import org.springframework.boot.context.properties.EnableConfigurationProperties; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import java.util.Locale;
@Configuration @EnableConfigurationProperties(BootstrapAdminProperties.class) public class BootstrapAdminConfiguration { @Bean ApplicationRunner bootstrapAdmin(BootstrapAdminProperties p,UsuarioRepository r,PasswordEncoder e){return args->criar(p,r,e);} @Transactional void criar(BootstrapAdminProperties p,UsuarioRepository r,PasswordEncoder e){if(!p.enabled())return;String email=p.email().trim().toLowerCase(Locale.ROOT);if(r.existsByEmailIgnoreCase(email))return;r.save(new Usuario(p.name().trim(),email,e.encode(p.password()),Papel.ADMIN,false));} }
